import{_ as e,c as r,o as l,ah as t,aj as i}from"./chunks/framework.e69F9EB5.js";const P=JSON.parse('{"title":"PCL.Mac 帮助文档 与 FAQ","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"helps/PCL.Mac.md","filePath":"helps/PCL.Mac.md"}'),o={name:"helps/PCL.Mac.md"};function c(s,a,n,p,h,d){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="pcl-mac-帮助文档-与-faq" tabindex="-1">PCL.Mac 帮助文档 与 FAQ <a class="header-anchor" href="#pcl-mac-帮助文档-与-faq" aria-label="Permalink to “PCL.Mac 帮助文档 与 FAQ”">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>本篇中的 PCL.Mac 指的是 <a href="/projects/PCL.Mac.Refactor.html">PCL.Mac.Refactor</a> 而非之前的 <a href="/projects/PCL.Mac.html">PCL.Mac</a>。</p></div><h2 id="download" tabindex="-1">下载启动器 <a class="header-anchor" href="#download" aria-label="Permalink to “下载启动器”">​</a></h2><p>你可以在 <a href="https://github.com/CylorineStudio/PCL.Mac.Refactor/releases" target="_blank" rel="noreferrer">GitHub Releases</a>、<a href="https://cnb.cool/CylorineStudio/PCL.Mac.Releases/-/releases" target="_blank" rel="noreferrer">CNB Releases</a>（国内镜像）或 <a href="https://qm.qq.com/q/GP6GegtjeW" target="_blank" rel="noreferrer">Cylorine Studio QQ群聊</a> 中下载 PCL.Mac。</p><h3 id="install" tabindex="-1">安装 <a class="header-anchor" href="#install" aria-label="Permalink to “安装”">​</a></h3><p>下载 <code>PCL.Mac-vX.X.X.dmg</code> 后，请将其打开，并将左边的“PCL.Mac”图标拖至右边的文件夹。</p><details><summary> 图片示例 </summary><img src="'+i+'"></details><p><s>如果在打开 App 时出现<a href="#qgatekeeper">报毒弹窗</a>，请打开 “系统设置”，在左侧找到 “隐私与安全性” 并点击，然后滚动到该页面的底部，点击 “已阻止 ‘PCL.Mac’ 以保护 Mac” 右边的 “仍然打开”。</s></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>（已过期）</strong><s>PCL.Mac 并不会危害你的电脑，出现这个弹窗只是因为没付费给 App 签名而已，以后会补上的（</s><br> 我们已为 <code>v1.0.1</code> 及以上的版本添加了签名与公证票据。如果您在打开 <code>v1.0.1</code> 及以上版本时出现了此弹窗，请<strong>立即删除该 App</strong>，并从<a href="#download">官方渠道</a>重新下载。</p></div><h2 id="multiplayer" tabindex="-1">联机 <a class="header-anchor" href="#multiplayer" aria-label="Permalink to “联机”">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>EasyTier 官方节点出现故障，联机功能暂时不可用。</p></div><p>PCL.Mac 的联机功能使用 EasyTier 工具实现，支持与不同局域网下的玩家联机。<br> 但，这个功能有一些限制：</p><ul><li>只支持在<strong>中国大陆</strong>地区内使用</li><li>需要使用<strong>正版账号</strong>加入游戏（若房主添加了 LAN Server Properties 等模组则无此限制）</li></ul><p>你可以通过该功能，与使用<strong>支持 Scaffolding 协议</strong>的启动器（HMCL、FCL、PCL CE、PCL.Mac 等）的玩家联机！<br></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>如果你和其他玩家在同一局域网内，无需使用该功能即可联机。<br><a href="https://zh.minecraft.wiki/w/Tutorial:%E6%9C%AC%E5%9C%B0%E5%B1%80%E5%9F%9F%E7%BD%91%E8%81%94%E6%9C%BA#Java%E7%89%88" target="_blank" rel="noreferrer">教程：本地局域网联机（Minecraft Wiki）</a></p></div><h3 id="房主" tabindex="-1">房主 <a class="header-anchor" href="#房主" aria-label="Permalink to “房主”">​</a></h3><ol><li>启动游戏并进入世界。</li><li>按下 ESC，点击 “对局域网开放”，调整配置并点击“创建局域网世界”。</li><li>记住聊天栏中的端口号（部分版本点击端口号可复制）。</li><li>打开 PCL.Mac，进入联机页面并点击“创建房间”。</li><li>点击“确定”，并输入端口号。</li><li>等待房间完成创建。</li><li>将房间码（创建房间后自动复制，也可以手动点击“复制房间码”）分享给你的好友。</li></ol><h3 id="房客" tabindex="-1">房客 <a class="header-anchor" href="#房客" aria-label="Permalink to “房客”">​</a></h3><ol><li>打开 PCL.Mac，进入联机页面并点击“加入房间”。</li><li>输入房间码。</li><li>启动游戏，进入“多人游戏”页面并点击“直接连接”。</li><li>输入地址（加入房间后自动复制，也可手动点击“复制地址”）并加入游戏。</li></ol><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><h4 id="qgatekeeper" tabindex="-1">Q：出现 “Apple 无法验证 ‘PCL.Mac’ 是否包含可能危害 Mac 安全或泄露隐私的恶意软件” 弹窗怎么办？ <a class="header-anchor" href="#qgatekeeper" aria-label="Permalink to “Q：出现 “Apple 无法验证 ‘PCL.Mac’ 是否包含可能危害 Mac 安全或泄露隐私的恶意软件” 弹窗怎么办？”">​</a></h4><p>A：请打开 “系统设置”，在左侧找到 “隐私与安全性” 并点击，然后滚动到该页面的底部，点击 “已阻止 ‘PCL.Mac’ 以保护 Mac” 右边的 “仍然打开”。</p><h4 id="qquarantine" tabindex="-1">Q：出现 “应用程序 ‘PCL.Mac’ 无法打开” “-47” 怎么办？ <a class="header-anchor" href="#qquarantine" aria-label="Permalink to “Q：出现 “应用程序 ‘PCL.Mac’ 无法打开” “-47” 怎么办？”">​</a></h4><p>A：请：</p><ol><li>打开终端</li><li>在终端中输入 <code>sudo xattr -r -d com.apple.quarantine </code>（末尾要带空格）</li><li>将 App 图标拖入终端窗口</li><li>按下回车键并输入密码</li><li>再次打开 App</li></ol><h5 id="group" tabindex="-1"><a class="header-anchor" href="#group" aria-label="Permalink to “”">​</a></h5><p>若要获取更多帮助，请加入 <a href="https://qm.qq.com/q/avBJcHq6I2" target="_blank" rel="noreferrer">Cylorine Studio QQ群聊</a> 或 <a href="https://qm.qq.com/q/P55hxAmgoY" target="_blank" rel="noreferrer">PCL.Mac 用户群</a>。</p>',27)])])}const b=e(o,[["render",c]]);export{P as __pageData,b as default};
